package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Stores the claim's new date, keeping its due-by and any figure a statement bound it to. Its period
 *  is the one its due-by falls in, so it stays as it is, and so does its number. */
public class ApplyRedate {
    public void apply(@Val RedateInput input, @Val Claim claim, ClaimStore store, Out<Redating> redating)
            throws InvalidSheetException {
        redating.set(redate(input, claim, store));
    }

    /** Stores the claim's new date: the re-dating, or refused when the claim has moved on. */
    static Redating redate(RedateInput input, Claim claim, ClaimStore store) throws InvalidSheetException {
        LocalDate old = claim.getDate();
        if (!store.redate(claim, input.date(), claim.getNumber())) {
            throw new InvalidSheetException("The claim has moved on");
        }
        return new Redating(old, input.date());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored re-dating: CLAIM_REDATED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<new yyyy-mm-dd> number=<n> old=<yyyy-mm-dd> new=<yyyy-mm-dd>. */
public class AuditClaimRedated {
    public void audit(@Val RedateInput input, @Val Claim claim, @Val Redating redating, @Val Rollup before,
            PersonStore people, Audit audit, RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_REDATED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " old=" + redating.old() + " new=" + redating.now());
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { peopleKey } from '../people/people';
import { claimsKey, useSelectedClaims } from './claims';

type BulkRedateResult = { redated: number; refused: number };

// Re-dates the selected claims together: the server re-dates each in list order by the rules of a
// single re-dating and refuses the rest, and the counts show once it answers (gone while it runs).
// Re-dating claims re-reads the people too: their figures follow the claims.
function BulkRedate() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [selected, setSelected] = useSelectedClaims();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();

  const bulk = useMutation({
    mutationFn: (claimIds: number[]) =>
      postJson<BulkRedateResult>(`/api/sheets/${encodeURIComponent(sheet)}/bulk-redate`, {
        claimIds: claimIds.map(String),
        date,
        user,
      }),
    onSuccess: async () => {
      setSelected([]);
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
  });
  const submit = useSubmitOnce(bulk);

  return (
    <p>
      <input
        type="date"
        data-testid="bulk-redate-date"
        aria-label="Re-date selected to"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          bulk.reset();
        }}
      />{' '}
      <button type="button" data-testid="bulk-redate" disabled={bulk.isPending} onClick={() => submit(selected)}>
        Re-date selected
      </button>
      {bulk.isSuccess && (
        <>
          {' '}
          Re-dated <strong data-testid="bulk-redated">{bulk.data.redated}</strong>, refused{' '}
          <strong data-testid="bulk-redate-refused">{bulk.data.refused}</strong>
        </>
      )}
      {bulk.isError && (
        <span data-testid="bulk-redate-error" role="alert">
          {' '}
          {bulk.error instanceof HttpError && bulk.error.reason ? `${bulk.error.reason}.` : 'The bulk re-date was refused.'}
        </span>
      )}
    </p>
  );
}

export const contribution = HomeMain.fill({ order: 24.5, Component: BulkRedate });
